import regex

with open('emoji.txt','r',encoding='utf-8') as f:
    data = f.read().strip()

# extract all emoji clusters in sequence
emojis = regex.findall(r'\X', data)
unique_emo = list(dict.fromkeys(emojis))
mapping = {emo: i for i, emo in enumerate(unique_emo)}
numlist = [mapping[e] for e in emojis]
results = {}
for base in [16, 20, 32]:
    num = 0
    for d in numlist:
        num = num * base + d
    nbytes = (num.bit_length() + 7) // 8
    b = num.to_bytes(nbytes, 'big')
    try:
        s = b.decode()
    except Exception:
        s = None
    results[base] = (b, s)

from re import findall
for base in results:
    b, s = results[base]
    print(f'=== BASE {base} ===')
    print('HEX:', b.hex())
    if s:
        print('ASCII:', s)
        f = findall(r'csawctf\{.*?\}', s)
        if f:
            print('\nFLAG:', f)
    else:
        from re import findall
        try:
            plain = b.decode('latin1')
            print('LATIN1:', plain)
            f = findall(r'csawctf\{.*?\}', plain)
            if f:
                print('\nFLAG:', f)
        except:
            pass
    print('\n')

# Try various base encodings, including grouping per 2, 3, 4 digits
indices = open('emoji_indices.txt').read().strip().split()
indices_ints = list(map(int, indices))
from base64 import b32decode

def try_bases():
    for base in [16, 20, 32, 36]:
        try:
            val = int(''.join([format(i, 'x') for i in indices_ints]), base)
            decoded_bytes = val.to_bytes((val.bit_length()+7)//8, 'big')
            print(f'Base {base} as bytes:', decoded_bytes)
            try:
                print(decoded_bytes.decode('utf-8'))
            except:
                print('-')
        except Exception as e:
            print(f'Base {base} error', e)
    # Try base 32 decode with padding
    s = ''.join([format(i, 'x') for i in indices_ints])
    # Add padding if needed
    pad = len(s) % 8
    if pad:
        s += '='*(8-pad)
    try:
        print('b32 try:', b32decode(s.upper(), casefold=True, map01=None))
    except Exception as e:
        print('b32 error', e)

    # Try as ascii directly per index
    brute = ''.join(chr(i+65) for i in indices_ints if i<26)
    print('A-Z mapping:', brute)

    # Try pairs as bytes
    out = b''
    for i in range(0,len(indices_ints)-1,2):
        out += bytes([indices_ints[i]*20 + indices_ints[i+1]])
    print('Base20 pairs:', out)
    try:
        print(out.decode())
    except:
        pass

try_bases()

