def try_decode_baseX(nums, base, block_size):
    result = []
    for i in range(0, len(nums), block_size):
        block = nums[i:i+block_size]
        if len(block) != block_size:
            continue
        val = 0
        for n in block:
            val = val * base + n
        try:
            text = val.to_bytes(block_size, 'big')
            result.append(text)
        except Exception as e:
            continue
    return b''.join(result)

